import { DomainError } from "./DomainError";

export class Product {
  constructor(
    readonly id: string,
    readonly name: string,
    private availableQuantity: number,
    private reservedQuantity: number = 0,
  ) {}

  get available(): number {
    return this.availableQuantity;
  }

  get reserved(): number {
    return this.reservedQuantity;
  }

  reserve(quantity: number): void {
    if (quantity > this.availableQuantity) {
      throw new DomainError("conflict", `Insufficient stock for product ${this.id}`);
    }
    this.availableQuantity -= quantity;
    this.reservedQuantity += quantity;
  }

  release(quantity: number): void {
    const released = Math.min(quantity, this.reservedQuantity);
    this.reservedQuantity -= released;
    this.availableQuantity += released;
  }
}

